<script setup lang="ts">
import { computed, shallowRef } from 'vue';
import { directorActions, totalFrames, type DirectorDocument } from '@/utils/dramaDirector';
const props = defineProps<{ document: DirectorDocument; frame: number; selected: string; selectedClip: string; playing: boolean }>();
const emit = defineEmits<{ seek: [frame: number]; play: []; select: [id: string]; addKey: []; clip: [objectId:string,id:string]; moveKey: [id:string,from:number,to:number,copy:boolean] }>();
const end = computed(() => totalFrames(props.document) - 1);
const ticks = computed(() => Array.from({length:Math.floor(props.document.duration/(props.document.duration>24?5:1))+1},(_,i)=>i*(props.document.duration>24?5:1)));
const tracks = computed(() => [{ id: 'camera', name: '摄影机 · 运镜', keys: props.document.camera.keys, clips:[] }, ...props.document.objects.map(o => ({id:o.id,name:o.name,keys:o.keys,clips:o.clips || []}))]);
const percent = (frame: number) => `${frame / end.value * 100}%`;
const drag = shallowRef<{id:string;from:number;to:number;left:number;width:number;x:number}>();
function down(event:PointerEvent,id:string,from:number) { if(props.playing)return; const button=event.currentTarget as HTMLButtonElement,rect=button.parentElement!.getBoundingClientRect(); button.setPointerCapture(event.pointerId);drag.value={id,from,to:from,left:rect.left,width:rect.width,x:event.clientX}; }
function move(event:PointerEvent) { if(!drag.value || Math.abs(event.clientX-drag.value.x)<4)return;drag.value={...drag.value,to:Math.max(0,Math.min(end.value,Math.round((event.clientX-drag.value.left)/drag.value.width*end.value)))}; }
function up(event:PointerEvent) { const d=drag.value;if(!d)return;drag.value=undefined;if(d.to!==d.from)emit('moveKey',d.id,d.from,d.to,event.altKey);else{emit('select',d.id);emit('seek',d.from);} }
function clickTrack(event:MouseEvent) { const rect=(event.currentTarget as HTMLElement).getBoundingClientRect();emit('seek',Math.round((event.clientX-rect.left)/rect.width*end.value)); }
</script>
<template>
  <section class="director-timeline" aria-label="导演预演时间轴">
    <header><div class="play-controls"><button aria-label="回到片段开始" @click="emit('seek',0)">|◀</button><button class="play" :aria-label="playing ? '暂停白模预演' : '播放白模预演'" @click="emit('play')">{{playing ? 'Ⅱ 暂停' : '▶ 播放'}}</button><button aria-label="到片段最后一帧" @click="emit('seek',end)">▶|</button><span>{{(frame/24).toFixed(2)}} <small>/ {{document.duration.toFixed(2)}}s</small></span><input aria-label="当前预演帧" type="number" :min="0" :max="end" :value="frame" @change="emit('seek',Number(($event.target as HTMLInputElement).value))"><small>帧</small></div><button :disabled="!selected" @click="emit('addKey')">◇ 添加关键帧</button></header>
    <div v-if="document.markers?.length" class="motion-markers"><button v-for="marker in document.markers" :key="`${marker.frame}-${marker.label}`" @click="emit('seek',marker.frame)">{{(marker.frame/24).toFixed(2)}}s · {{marker.label}}</button></div>
    <div class="time-ruler"><span>时间 / 24 FPS</span><div><i v-for="s in ticks" :key="s" :style="{left:`${s/document.duration*100}%`}">{{s}}s</i><input aria-label="预演时间轴" type="range" min="0" :max="end" step="1" :value="frame" @input="emit('seek',Number(($event.target as HTMLInputElement).value))"></div></div>
    <div class="tracks"><div v-for="track in tracks" :key="track.id" class="track-group" :class="{selected:track.id===selected}"><div class="track"><button class="track-name" @click="emit('select',track.id)">{{track.name}}</button><div class="track-line" @click.self="clickTrack"><div class="playhead" :style="{left:percent(frame)}"/><button v-for="k in track.keys" :key="k.frame" class="key-dot" :style="{left:percent(drag?.id===track.id && drag.from===k.frame ? drag.to : k.frame)}" :aria-label="`${track.name} ${k.frame}帧关键帧`" :title="`${k.frame} 帧 · 拖动移动，Alt 拖动复制`" @pointerdown.stop="down($event,track.id,k.frame)" @pointermove.stop="move" @pointerup.stop="up" @pointercancel="drag=undefined" @click.stop @keydown.enter="emit('select',track.id);emit('seek',k.frame)"/></div></div><div v-if="track.clips.length" class="track action-track"><span class="track-name action-label">动作编排</span><div class="track-line" @click.self="clickTrack"><div class="playhead" :style="{left:percent(frame)}"/><button v-for="c in track.clips" :key="c.id" class="action-block" :class="{active:track.id===selected && c.id===selectedClip}" :style="{left:`${c.start/(end+1)*100}%`,width:`${(c.end-c.start)/(end+1)*100}%`}" :aria-label="`${track.name} ${directorActions[c.action]}动作片段`" :title="`${directorActions[c.action]} ${(c.start/24).toFixed(2)}–${(c.end/24).toFixed(2)}s`" @click.stop="emit('clip',track.id,c.id)">{{directorActions[c.action]}}</button></div></div></div></div>
    <footer v-if="drag">{{drag.to}} 帧 · 松开{{drag.from===0 ? '（第 0 帧请按 Alt 复制）' : '移动，按 Alt 复制'}}</footer>
  </section>
</template>
<style scoped>
.motion-markers{display:flex;gap:5px;overflow:auto;flex:none;padding:0 0 6px}.motion-markers button{white-space:nowrap;background:#eff5fd!important;border-radius:4px;font-size:9px!important;padding:5px 8px!important}
.director-timeline{background:#fff;border-top:1px solid #d9e3ef;display:flex;flex-direction:column;min-height:0;padding:0 20px;color:#546b87}.director-timeline header{display:flex;justify-content:space-between;align-items:center;height:48px;flex:none}.director-timeline button{background:transparent;border:0;font:11px inherit;color:#617895;cursor:pointer;padding:7px 9px}.director-timeline button:disabled{opacity:.4}.play-controls{display:flex;align-items:center;gap:6px;font-variant-numeric:tabular-nums}.play-controls .play{background:#edf4ff;color:#2a72d0;border-radius:5px;min-width:68px}.play-controls span{font-size:12px;color:#385c8c;margin:0 10px}.play-controls small{font-size:10px;color:#9aa9be}.play-controls input{width:40px;border:1px solid #e1e8f1;border-radius:4px;padding:4px;font-size:10px;color:#607594}.time-ruler{display:flex;height:27px;align-items:start;font-size:9px;color:#97a7bd;flex:none}.time-ruler>span{width:144px;flex:none;padding-top:5px}.time-ruler>div{flex:1;position:relative;margin-right:5px}.time-ruler i{position:absolute;font-style:normal;top:0;transform:translateX(-50%)}.time-ruler input{position:absolute;top:10px;left:-6px;width:calc(100% + 12px);height:12px;margin:0;accent-color:#3b81df;cursor:ew-resize}.tracks{overflow:auto;flex:1;min-height:0;padding-right:5px;padding-bottom:9px}.track{display:flex;align-items:center;height:28px;border-top:1px solid #f0f3f8}.track-name{width:144px;flex:none;text-align:left;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:10px!important}.track-group.selected .track-name{color:#2e75d5}.track-line{position:relative;height:24px;flex:1;cursor:crosshair;border-left:1px solid #d7e4f5;background:repeating-linear-gradient(90deg,transparent,transparent calc(12.5% - 1px),#edf1f6 calc(12.5% - 1px),#edf1f6 12.5%)}.track-group.selected .track-line{background-color:#f4f8ff}.track-line .key-dot{position:absolute;top:9px;width:7px;height:7px;background:#8fb2df;transform:translateX(-50%) rotate(45deg);padding:0;border:1px solid #fff}.track-group.selected .key-dot{background:#3a80dc}.playhead{position:absolute;inset:0 auto;width:1px;background:#548cda;pointer-events:none}
.key-dot{touch-action:none;cursor:ew-resize!important}.action-track{height:25px;border-top:0}.action-label{box-sizing:border-box;padding-left:22px;font-size:9px;color:#99aac0}.action-block{position:absolute;top:3px;height:19px;border:1px solid #b5cee9!important;border-radius:3px;background:#e9f2fd!important;color:#5b84b4!important;font-size:9px!important;padding:2px 6px!important;box-sizing:border-box;text-align:left;overflow:hidden;white-space:nowrap}.action-block.active{background:#d9eaff!important;border-color:#4f90dd!important;color:#286bbd!important}.director-timeline footer{font-size:9px;color:#6587b4;padding-bottom:8px}
</style>
